class Node:
    def __init__(self, key):
        self.left = None
        self.right = None
        self.val = key

def createTree(parent, N):
    nodes = [None] * N
    root = None

    for i in range(N):
        nodes[i] = Node(i)

    for i in range(N):
        if parent[i] == -1:
            root = nodes[i]
        else:
            if nodes[parent[i]].left is None:
                nodes[parent[i]].left = nodes[i]
            else:
                nodes[parent[i]].right = nodes[i]

    return root

def inorderTraversal(root):
    if root:
        inorderTraversal(root.left)
        print(root.val, end=' ')
        inorderTraversal(root.right)

import sys
input = sys.stdin.read
data = input().split()
N = int(data[0])
parent = list(map(int, data[1:]))
root = createTree(parent, N)
inorderTraversal(root)
